export function createPrayEnvironment(services,layout,namespace) {
    for(const[k,v]of Object.entries({pointerSize:8,longSize:8,vaListSize:8,intSize:4,charSigned:1,littleEndian:1}))
        if(layout[k]!==v)throw Error('Review changed PRAY ABI: '+k);
    const ptr=v=>{const n=Number(v);if(!Number.isSafeInteger(n)||BigInt(n)!==BigInt(v))throw Error('PRAY pointer exceeds exact address range');return n;};
    const types={char:'i8','signed char':'i8','unsigned char':'u8',short:'i16','unsigned short':'u16',int:'i32','unsigned int':'u32',unsigned:'u32',long:'i64','unsigned long':'u64','long long':'i64','unsigned long long':'u64'};
    const env=Object.assign(Object.create(services),layout,{ptr,sizes:Object.fromEntries(Object.entries(layout).filter(([k])=>k.startsWith('size:')).map(([k,v])=>[k.slice(5),v]))});
    for(const signed of ['i','u'])for(const bits of [8,16,32,64])env[signed+bits]=v=>{const n=BigInt[signed==='i'?'asIntN':'asUintN'](bits,BigInt(typeof v==='number'?Math.trunc(v):v));return bits===64?n:Number(n);};
    const memory=()=>new DataView(services.heap().buffer),type=t=>t.includes('*')?'p':t.startsWith('enum ')?'i32':types[t];
    const decode=(t,v)=>{const d=type(t);if(d==='p')return ptr(v);if(!d)throw Error('Review PRAY scalar type '+t);return env[d](v);};
    env.cell=(address,t)=>{address=ptr(address);const d=type(t);if(!d)throw Error('Review PRAY cell type '+t);const bits=d==='p'?64:+d.slice(1);return {address,get value(){const dv=memory();return decode(t,bits===64?dv.getBigUint64(address,true):dv['getUint'+bits](address,true));},set value(v){const dv=memory();if(bits===64)dv.setBigUint64(address,BigInt.asUintN(64,BigInt(v)),true);else dv['setUint'+bits](address,Number(v),true);}};};
    const kinds=Object.keys(schema.schema);
    env.field=(at,name,field)=>{const kind=kinds.indexOf(name),index=schema.schema[name]?.fields.findIndex(f=>f.name===field),f=schema.schema[name]?.fields[index];if(kind<0||index<0||!f)throw Error('Review PRAY field '+name+'.'+field);at=ptr(at);return {get address(){return ptr(services.address(kind,at,index));},get value(){return decode(f.canonical,services.read(kind,at,index));},set value(v){services.write(kind,at,index,BigInt.asUintN(64,BigInt(v)));}};};
    schema.globals.forEach((g,i)=>Object.defineProperty(env,g.name,{get:()=>ptr(services.global(i))}));
    env.global=name=>{const g=schema.globals.find(g=>g.name===name);if(!g)throw Error('Review PRAY global '+name);return env.cell(env[name],g.canonical);};
    const staticBase=ptr(services.global(schema.globals.length)),initialized=new Set();
    env.staticArray=(owner,name,text)=>{const row=schema.localStatics.find(row=>row.owner===owner&&row.name===name);if(!row||row.text!==text)throw Error('Review PRAY local static '+owner+'.'+name);const key=owner+'.'+name,at=staticBase+row.offset;if(!initialized.has(key)){services.staticString(at,text,row.bytes);initialized.add(key);}return at;};
    Object.assign(env,namespace.initialState(env));
    Object.freeze(env.godvoices);Object.freeze(env.hallu_gods);
    if(env.godvoices.length!==4||env.hallu_gods.length!==14)throw Error('Review PRAY source table');
    env.functionPointer=name=>{const fn=services.functionPointers[name];if(!fn)throw Error('Review PRAY function pointer '+name);return ptr(fn());};
    env.callProc=(fn,prototype,...args)=>{if(prototype==='int (int)')return services.callRng(fn,...args);if(prototype==='void (winid, boolean)')return services.callWindow(fn,...args);throw Error('Review PRAY callback prototype '+prototype);};
    env.variadic=(site,...args)=>{const entry=schema.variadics[site];if(!entry||entry.site!==site)throw Error('Review PRAY varargs site');return services['var'+site](...args);};
    return env;
}
